import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.DpXDHk3d.js";const g=JSON.parse('{"title":"11.1 雷电危害与防雷装置","description":"","frontmatter":{},"headers":[],"relativePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-1-lei-dian-wei-hai-yu-fang-lei-zhuang-zhi.md","filePath":"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-1-lei-dian-wei-hai-yu-fang-lei-zhuang-zhi.md","lastUpdated":1793096070000}'),e={name:"electrician/low-voltage-electrician/11-chapter-11-fang-lei-yu-jie-di/11-1-lei-dian-wei-hai-yu-fang-lei-zhuang-zhi.md"};function n(r,t,s,d,h,u){return l(),i("div",null,[...t[0]||(t[0]=[o(`<h1 id="_11-1-雷电危害与防雷装置" tabindex="-1">11.1 雷电危害与防雷装置 <a class="header-anchor" href="#_11-1-雷电危害与防雷装置" aria-label="Permalink to &quot;11.1 雷电危害与防雷装置&quot;">​</a></h1><h2 id="本节导读" tabindex="-1">本节导读 <a class="header-anchor" href="#本节导读" aria-label="Permalink to &quot;本节导读&quot;">​</a></h2><p>雷击的电压可以高达几百万伏,是电气设备的&quot;天敌&quot;。这一节认识雷电的危害形式,以及避雷针、避雷器、引下线、接地装置组成的&quot;防雷四件套&quot;。</p><h2 id="一、雷电是怎样产生的" tabindex="-1">一、雷电是怎样产生的 <a class="header-anchor" href="#一、雷电是怎样产生的" aria-label="Permalink to &quot;一、雷电是怎样产生的&quot;">​</a></h2><p>雷雨云之间或雷雨云与地面之间发生强烈放电,就形成雷电:</p><ul><li>雷雨云带电,地面感应出异性电荷;</li><li>电荷积累到一定程度,云与地之间发生<strong>击穿放电</strong>,产生强大电流。</li></ul><h2 id="二、雷电的危害-三类效应" tabindex="-1">二、雷电的危害(三类效应) <a class="header-anchor" href="#二、雷电的危害-三类效应" aria-label="Permalink to &quot;二、雷电的危害(三类效应)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>危害</th><th>表现</th></tr></thead><tbody><tr><td><strong>电效应(过电压)</strong></td><td>雷击产生几百万伏过电压,击穿设备绝缘、烧毁电器</td></tr><tr><td><strong>热效应</strong></td><td>雷电流通过导体发热,可能烧熔导线、引发火灾</td></tr><tr><td><strong>机械效应(力效应)</strong></td><td>雷电冲击力破坏建筑物、树木、杆塔</td></tr></tbody></table><blockquote><p>💡 记忆:<strong>雷电三效应 = 电(电压)、热(发热)、力(冲击)</strong>。</p></blockquote><h2 id="三、雷电的两种形式-对设备而言" tabindex="-1">三、雷电的两种形式(对设备而言) <a class="header-anchor" href="#三、雷电的两种形式-对设备而言" aria-label="Permalink to &quot;三、雷电的两种形式(对设备而言)&quot;">​</a></h2><ol><li><strong>直击雷</strong>:雷电直接击中设备或建筑物——破坏力最大;</li><li><strong>感应雷(感应过电压)</strong>:雷击附近时,电磁感应在线路上产生高电压——同样能击坏电气设备。</li></ol><blockquote><p>⚠️ 判断题常考:感应雷(雷电感应)也会在线路、设备上产生过电压,损坏设备。</p></blockquote><h2 id="四、防雷装置-四大件" tabindex="-1">四、防雷装置:四大件 <a class="header-anchor" href="#四、防雷装置-四大件" aria-label="Permalink to &quot;四、防雷装置:四大件&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>接闪器(避雷针/带/网)</span></span>
<span class="line"><span>    │ 把雷电流接住</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>引下线(粗铜/钢线)──把雷电流引到地下</span></span>
<span class="line"><span>    ▼</span></span>
<span class="line"><span>接地装置(接地体+接地线)──把雷电流泄入大地</span></span></code></pre></div><table tabindex="0"><thead><tr><th>部件</th><th>作用</th></tr></thead><tbody><tr><td><strong>接闪器</strong></td><td>把雷电流&quot;接住&quot;再引走(避雷针、避雷带、避雷网)</td></tr><tr><td><strong>引下线</strong></td><td>把接闪器的雷电流<strong>引到接地装置</strong>,截面足够大</td></tr><tr><td><strong>接地装置</strong></td><td>把雷电流<strong>泄入大地</strong>,接地电阻要小</td></tr><tr><td><strong>避雷器</strong></td><td>并联在<strong>电气设备/线路</strong>旁,雷击时把过电压泄放、保护设备</td></tr></tbody></table><blockquote><p>💡 通俗理解:<strong>避雷针保护&quot;建筑&quot;,避雷器保护&quot;电器&quot;</strong>。避雷针主动接雷;避雷器平时绝缘、雷击时导通泄流、雷过后又恢复。</p></blockquote><h2 id="五、避雷针的保护原理" tabindex="-1">五、避雷针的保护原理 <a class="header-anchor" href="#五、避雷针的保护原理" aria-label="Permalink to &quot;五、避雷针的保护原理&quot;">​</a></h2><ul><li>避雷针<strong>高于被保护物</strong>,把雷引向自身,让雷电流沿引下线入地,被保护物不受雷击——所以避雷针其实是&quot;<strong>引雷针</strong>&quot;;</li><li>保护范围:以避雷针为轴线的<strong>圆锥形区域</strong>。</li></ul><blockquote><p>⚠️ 判断题常考:避雷针是把雷引到自己身上再导入地下,从而保护周围物体;它不是&quot;把雷挡开&quot;,而是&quot;把雷引走&quot;。</p></blockquote><h2 id="六、防雷与接地" tabindex="-1">六、防雷与接地 <a class="header-anchor" href="#六、防雷与接地" aria-label="Permalink to &quot;六、防雷与接地&quot;">​</a></h2><ul><li>防雷装置的接地称<strong>防雷接地</strong>,接地电阻要求较小(独立避雷针一般不大于 10Ω);</li><li>高层建筑的防雷接地、电气设备的保护接地等应合理布置。</li></ul><h2 id="七、考点提示" tabindex="-1">七、考点提示 <a class="header-anchor" href="#七、考点提示" aria-label="Permalink to &quot;七、考点提示&quot;">​</a></h2><ul><li>✅ 雷电三效应:电效应、热效应、机械效应。</li><li>✅ 防雷装置:接闪器(避雷针/带/网)、引下线、接地装置,加避雷器保护电器。</li><li>✅ 避雷针的作用是<strong>引雷入地</strong>。</li><li>⚠️ 易混点:避雷针(引雷、保护建筑)vs 避雷器(泄放过电压、保护设备)。</li></ul><h2 id="八、本节小结" tabindex="-1">八、本节小结 <a class="header-anchor" href="#八、本节小结" aria-label="Permalink to &quot;八、本节小结&quot;">​</a></h2><ul><li>雷电的危害:过电压、发热、冲击破坏。</li><li>防雷靠&quot;接雷、引下、入地&quot;三件套;设备再靠避雷器保护。</li><li>避雷针不是挡雷,而是主动把雷引走。</li></ul><h2 id="九、自测练习" tabindex="-1">九、自测练习 <a class="header-anchor" href="#九、自测练习" aria-label="Permalink to &quot;九、自测练习&quot;">​</a></h2><ol><li>(判断)避雷针的作用是把雷电引向自身并导入地下,保护周围物体。( )</li><li>(单选)下列属于防雷装置的是()。 A. 避雷针　B. 熔断器　C. 漏电保护器　D. 热继电器</li><li>(判断)雷击建筑物时,强大的电流通过导体发热,可能引发火灾,这是雷电的热效应。( )</li><li>(单选)主要用来保护电气设备免遭雷电过电压损坏的装置是()。 A. 避雷针　B. 避雷器　C. 引下线　D. 接地体</li><li>(判断)感应雷(雷电感应)也会在设备线路上产生过电压。( )</li></ol><details><summary>参考答案(点击展开)</summary><ol><li><strong>√</strong>。避雷针是&quot;引雷入地&quot;,保护其周围物体。</li><li><strong>A</strong>。避雷针属防雷装置。</li><li><strong>√</strong>。雷电流发热引起火灾是热效应。</li><li><strong>B</strong>。避雷器保护电气设备免遭过电压损坏。</li><li><strong>√</strong>。感应雷同样会产生过电压损坏设备。</li></ol></details>`,28)])])}const p=a(e,[["render",n]]);export{g as __pageData,p as default};
